    /// <summary>
    /// Changes the list of keywords of a sticker. The sticker must belong to a regular or custom emoji sticker set that is owned by the current user
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetStickerKeywordsAsync(InputFile sticker = default, string[] keywords = default)
    {

           using var activity =  StartCallActivity("SetStickerKeywordsAsync", typeof(SetStickerKeywords).FullName ?? "SetStickerKeywordsAsync");

           try
           {
             return client.SetStickerKeywordsAsync(sticker, keywords);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
